INSERT INTO `companies` VALUES (1,'VIET NAM','2026-07-11 16:02:45.295386','admin@gmail.com','<p><strong>VinFast</strong> (thành lập năm 2017 thuộc Tập đoàn Vingroup) là biểu tượng cho khát vọng công nghiệp hóa và toàn cầu hóa của Việt Nam. Khởi đầu từ một tổ hợp nhà máy hiện đại tại Hải Phòng với các dòng xe xăng chiếm lĩnh thị trường nội địa, VinFast đã có bước chuyển mình lịch sử vào năm 2022 khi tuyên bố dừng xe xăng để trở thành hãng xe thuần điện 100%. Hiện tại, thương hiệu đã sở hữu một hệ sinh thái di chuyển xanh đa dạng từ xe máy điện, xe buýt điện VinBus cho đến dải ô tô điện trải dài mọi phân khúc từ VF 3 (mini-SUV) đến VF 9 (SUV cỡ lớn). Không chỉ khẳng định vị thế trong nước thông qua sự phổ cập của hãng taxi Xanh SM, VinFast còn mạnh mẽ vươn tầm quốc tế khi niêm yết trên sàn chứng khoán Nasdaq (Mỹ) và đang tích cực mở rộng thị trường, xây dựng nhà máy tại Mỹ, Ấn Độ và Indonesia nhằm hiện thực hóa mục tiêu thúc đẩy cuộc cách mạng giao thông xanh toàn cầu.</p>','1783785708594-vinfast-logo-png_seeklogo-425050.png','VINFAST','2026-07-11 16:10:44.237889','admin@gmail.com',_binary ''),(2,'USA','2026-07-11 16:05:41.154212','admin@gmail.com','<p><strong>Tesla, Inc.</strong> (tiền thân là Tesla Motors) là một công ty đa quốc gia của Mỹ, được thành lập vào năm 2003 bởi một nhóm kỹ sư, trong đó có Martin Eberhard và Marc Tarpenning, trước khi <strong>Elon Musk</strong> tham gia đầu tư lớn vào năm 2004 và trở thành CEO dẫn dắt công ty như ngày nay. Có trụ sở chính tại Austin, Texas, Tesla không chỉ đơn thuần là một hãng sản xuất ô tô mà tự định vị mình là một công ty năng lượng và công nghệ hàng đầu thế giới, với sứ mệnh tăng tốc sự chuyển dịch của nhân loại sang năng lượng bền vững.</p>','1783785915091-Tesla-Logo.jpg','TESLA',NULL,NULL,_binary ''),(3,'Germany','2026-07-11 16:10:33.430767','admin@gmail.com','<p><strong>Mercedes-Benz</strong> (thường gọi ngắn gọn là Mercedes) là một trong những thương hiệu ô tô lâu đời, danh tiếng và thành công nhất mọi thời đại. Thương hiệu này thuộc sở hữu của tập đoàn xe sang <strong>Mercedes-Benz Group AG</strong> (trước đây là Daimler AG), có trụ sở chính tại Stuttgart, bang Baden-Württemberg, Đức.</p>','1783786181371-Mercedes-Benz-Logo-PNG-Images.png','Mercedes-Benz Group AG',NULL,NULL,_binary ''),(4,'CHINA','2026-07-11 16:12:55.083262','admin@gmail.com','<p><strong>MG</strong> (Morris Garages, thành lập năm 1924 tại Anh) là thương hiệu ô tô mang tính bước ngoặt khi kết hợp hài hòa giữa <strong>di sản thiết kế Anh Quốc</strong> và <strong>năng lực công nghệ vượt trội của tập đoàn mẹ SAIC Motor (Trung Quốc)</strong> – một trong những gã khổng lồ ô tô lớn nhất thế giới. Trải qua một thế kỷ phát triển, từ một hãng xe thể thao mui trần cổ điển biểu tượng của xứ sở sương mù, MG hiện nay đã lột xác thành thương hiệu xe phổ thông toàn cầu, tập trung vào phong cách thiết kế trẻ trung, tràn ngập công nghệ thông minh và mức giá cực kỳ cạnh tranh. Tại thị trường Việt Nam, dưới sự quản lý trực tiếp của SAIC Motor Việt Nam (SMV), dải sản phẩm nhập khẩu từ Thái Lan và Trung Quốc như MG5, ZS, HS hay mẫu xe điện tiên phong MG4 EV đang ngày càng khẳng định vị thế nhờ chiến lược \"trang bị vượt tầm giá\" kết hợp chính sách hậu mãi hấp dẫn, trở thành lựa chọn tối ưu cho nhóm khách hàng trẻ hiện đại.</p>','1783786340710-mg.png','MG',NULL,NULL,_binary ''),(8,'Mountain View, California, Hoa Kỳ','2026-09-30 04:08:55.264206','admin@gmail.com','<p>Google được thành lập năm 1998, có trụ sở chính tại Mountain View, California (Hoa Kỳ) và là công ty con của Alphabet Inc. từ năm 2015.</p><p>Các sản phẩm tiêu biểu gồm Google Search, Android, YouTube, Chrome, Gmail, Google Cloud và dòng thiết bị Pixel. Singapore là trụ sở khu vực châu Á – Thái Bình Dương của Google. Tại Hà Nội, Google tuyển dụng các vị trí kỹ thuật liên quan đến chất lượng sản xuất thiết bị Pixel.</p>','','Google',NULL,NULL,_binary ''),(9,'Cupertino, California, Hoa Kỳ','2026-09-30 04:08:55.279882','admin@gmail.com','<p>Apple được thành lập năm 1976, có trụ sở chính tại Cupertino, California (Hoa Kỳ).</p><p>Công ty thiết kế và phát triển iPhone, iPad, Mac, Apple Watch cùng các hệ điều hành iOS, macOS và các dịch vụ như App Store, iCloud, Apple Music. Apple có văn phòng tại Singapore và tuyển dụng nhiều vị trí kỹ thuật phần mềm tại đây.</p>','','Apple',NULL,NULL,_binary ''),(10,'Redmond, Washington, Hoa Kỳ','2026-09-30 04:08:55.296793','admin@gmail.com','<p>Microsoft được thành lập năm 1975, có trụ sở chính tại Redmond, Washington (Hoa Kỳ).</p><p>Các sản phẩm và dịch vụ chính gồm hệ điều hành Windows, bộ ứng dụng Microsoft 365, nền tảng điện toán đám mây Azure và hệ máy chơi game Xbox. Microsoft cũng sở hữu LinkedIn và GitHub. Ngoài Hoa Kỳ, công ty có trung tâm phát triển lớn tại Hyderabad (Ấn Độ).</p>','','Microsoft',NULL,NULL,_binary ''),(11,'San Francisco, California, Hoa Kỳ','2026-09-30 04:08:55.308279','admin@gmail.com','<p>Anthropic là công ty nghiên cứu và an toàn AI được thành lập năm 2021, có trụ sở chính tại San Francisco, California (Hoa Kỳ).</p><p>Công ty phát triển dòng mô hình ngôn ngữ lớn Claude, cung cấp qua ứng dụng Claude và qua API cho doanh nghiệp, lập trình viên. Anthropic có văn phòng tại London, Tokyo, Seoul, Bengaluru, Sydney và đã công bố mở văn phòng đầu tiên ở Đông Nam Á tại Singapore.</p>','','Anthropic',NULL,NULL,_binary ''),(12,'San Francisco, California, Hoa Kỳ','2026-09-30 04:08:55.318140','admin@gmail.com','<p>OpenAI được thành lập năm 2015, có trụ sở chính tại San Francisco, California (Hoa Kỳ).</p><p>Công ty phát triển các mô hình AI như dòng GPT và sản phẩm ChatGPT ra mắt cuối năm 2022, đồng thời cung cấp nền tảng API cho doanh nghiệp và lập trình viên. OpenAI có văn phòng tại London, Dublin, Tokyo, Singapore và một số thành phố khác.</p>','','OpenAI',NULL,NULL,_binary ''),(13,'Menlo Park, California, Hoa Kỳ','2026-09-30 04:08:55.329511','admin@gmail.com','<p>Meta Platforms được thành lập năm 2004 với tên Facebook và đổi tên thành Meta vào năm 2021. Trụ sở chính đặt tại Menlo Park, California (Hoa Kỳ).</p><p>Công ty vận hành các nền tảng Facebook, Instagram, WhatsApp, Messenger và Threads, đồng thời phát triển thiết bị thực tế ảo Meta Quest. Meta là đơn vị khởi xướng các dự án mã nguồn mở React và PyTorch, và có văn phòng tại Singapore.</p>','','Meta',NULL,NULL,_binary ''),(14,'Seattle, Washington, Hoa Kỳ','2026-09-30 04:08:55.341187','admin@gmail.com','<p>Amazon được thành lập năm 1994, có trụ sở chính tại Seattle, Washington (Hoa Kỳ).</p><p>Bên cạnh thương mại điện tử, Amazon vận hành Amazon Web Services (AWS) – nền tảng điện toán đám mây ra mắt năm 2006 – cùng các dịch vụ như Prime, Alexa và Kindle. Tại Việt Nam, AWS có đội ngũ ở Hà Nội và TP. Hồ Chí Minh, tuyển dụng các vị trí kiến trúc giải pháp và triển khai đám mây.</p>','','Amazon',NULL,NULL,_binary ''),(15,'TP. Hồ Chí Minh, Việt Nam','2026-09-30 04:08:55.353661','admin@gmail.com','<p>Zalo là ứng dụng nhắn tin và gọi điện miễn phí do VNG phát triển, ra mắt năm 2012.</p><p>Theo số liệu VNG công bố, tính đến tháng 12/2025 Zalo có khoảng 79,6 triệu người dùng hoạt động hằng tháng. Ngoài nhắn tin, Zalo cung cấp Zalo Official Account và Zalo Mini App cho doanh nghiệp. Đội ngũ phát triển sản phẩm làm việc tại TP. Hồ Chí Minh.</p>','','Zalo',NULL,NULL,_binary ''),(16,'TP. Hồ Chí Minh, Việt Nam','2026-09-30 04:08:55.366291','admin@gmail.com','<p>MoMo là thương hiệu của Công ty Cổ phần Dịch vụ Di Động Trực tuyến (M_Service), được thành lập năm 2007 và có trụ sở tại TP. Hồ Chí Minh.</p><p>Ứng dụng ví điện tử MoMo ra mắt năm 2014 và được Ngân hàng Nhà nước cấp phép cung cấp dịch vụ ví điện tử. Người dùng có thể chuyển tiền, thanh toán hóa đơn và thanh toán bằng mã QR. Công ty ứng dụng machine learning trong phát hiện gian lận và cá nhân hóa trải nghiệm.</p>','','MoMo',NULL,NULL,_binary ''),(17,'Z06 Đường số 13, Phường Tân Thuận, TP. Hồ Chí Minh, Việt Nam','2026-09-30 04:08:55.376794','admin@gmail.com','<p>VNG là công ty công nghệ Việt Nam được thành lập năm 2004, có trụ sở tại TP. Hồ Chí Minh.</p><p>Hệ sinh thái của VNG gồm trò chơi trực tuyến (VNGGames, ZingPlay), nền tảng nhắn tin Zalo, ứng dụng thanh toán Zalopay và dịch vụ điện toán đám mây, hạ tầng AI (VNG Cloud, GreenNode). Công ty tuyển dụng thường xuyên các vị trí kỹ thuật, sản phẩm và thiết kế.</p>','','VNG',NULL,NULL,_binary ''),(18,'Santa Clara, California, Hoa Kỳ','2026-09-30 10:02:38.700705','admin@gmail.com','<p>NVIDIA được thành lập năm 1993 và có trụ sở tại Santa Clara, California. Công ty tiên phong trong bộ xử lý đồ họa (GPU) và là nền tảng tính toán cho trí tuệ nhân tạo, trung tâm dữ liệu, xe tự lái và đồ họa chuyên nghiệp.</p><p>Nền tảng lập trình song song CUDA cùng các thư viện, framework AI của NVIDIA được cộng đồng nghiên cứu và doanh nghiệp trên toàn cầu sử dụng. Tháng 12/2024, NVIDIA công bố mở trung tâm nghiên cứu và phát triển đầu tiên tại Việt Nam, tập trung vào phát triển phần mềm AI.</p>','','NVIDIA',NULL,NULL,_binary ''),(19,'Hawthorne, California, Hoa Kỳ','2026-09-30 10:02:38.726076','admin@gmail.com','<p>SpaceX (Space Exploration Technologies Corp.) được thành lập năm 2002 bởi Elon Musk với mục tiêu giảm chi phí đưa tải trọng vào không gian và hướng tới việc đưa con người lên sao Hỏa. Công ty có trụ sở tại Hawthorne, California và khu vực sản xuất, thử nghiệm Starship tại Starbase, Texas.</p><p>SpaceX phát triển tên lửa tái sử dụng Falcon 9 và Falcon Heavy, tàu vũ trụ Dragon, hệ thống Starship và chòm vệ tinh internet Starlink. Phần mềm bay, hệ thống nhúng và hạ tầng mặt đất là những mảng kỹ thuật trọng yếu của công ty.</p>','','SpaceX',NULL,NULL,_binary ''),(20,'Los Gatos, California, Hoa Kỳ','2026-09-30 10:02:38.751581','admin@gmail.com','<p>Netflix được thành lập năm 1997 bởi Reed Hastings và Marc Randolph, hiện có trụ sở tại Los Gatos, California. Đây là dịch vụ truyền phát phim, chương trình truyền hình và trò chơi có mặt tại hơn 190 quốc gia.</p><p>Đội ngũ kỹ thuật của Netflix xây dựng hạ tầng phát video quy mô lớn, hệ thống gợi ý cá nhân hóa, nền tảng dữ liệu và các ứng dụng chạy trên Android, iOS, TV thông minh và trình duyệt web.</p>','','Netflix',NULL,NULL,_binary ''),(21,'Suwon, Hàn Quốc','2026-09-30 10:02:38.776703','admin@gmail.com','<p>Samsung Electronics được thành lập năm 1969, có trụ sở tại Suwon, Hàn Quốc, và là một trong những nhà sản xuất điện thoại, bán dẫn, màn hình và thiết bị gia dụng lớn nhất thế giới.</p><p>Tại Việt Nam, Samsung có các nhà máy ở Bắc Ninh và Thái Nguyên, tổ hợp thiết bị gia dụng tại TP. Hồ Chí Minh và Trung tâm Nghiên cứu và Phát triển tại Hà Nội (SRV), được xem là trung tâm R&D lớn nhất của Samsung tại Đông Nam Á với hàng nghìn kỹ sư phần mềm.</p>','','Samsung',NULL,NULL,_binary ''),(22,'Santa Clara, California, Hoa Kỳ','2026-09-30 10:02:38.801444','admin@gmail.com','<p>Intel được thành lập năm 1968 bởi Gordon Moore và Robert Noyce, có trụ sở tại Santa Clara, California. Công ty thiết kế và sản xuất bộ vi xử lý, chipset, bộ nhớ và các giải pháp cho máy tính, trung tâm dữ liệu và thiết bị biên.</p><p>Intel Products Vietnam đặt tại Khu Công nghệ cao TP. Hồ Chí Minh (Thủ Đức), là cơ sở lắp ráp và kiểm thử chip lớn nhất trong mạng lưới sản xuất toàn cầu của Intel, với nhiều vị trí kỹ sư kiểm thử, tự động hóa và phân tích dữ liệu sản xuất.</p>','','Intel',NULL,NULL,_binary ''),(23,'Santa Clara, California, Hoa Kỳ','2026-09-30 10:02:38.827652','admin@gmail.com','<p>AMD (Advanced Micro Devices) được thành lập năm 1969 và có trụ sở tại Santa Clara, California. Công ty thiết kế bộ vi xử lý Ryzen và EPYC, card đồ họa Radeon, bộ tăng tốc AI Instinct cùng các giải pháp FPGA sau khi hợp nhất với Xilinx năm 2022.</p><p>Các nhóm kỹ thuật của AMD làm việc về kiến trúc GPU, kiểm chứng thiết kế, firmware, trình biên dịch và nền tảng phần mềm ROCm cho tính toán hiệu năng cao và học máy.</p>','','AMD',NULL,NULL,_binary ''),(24,'Tầng 8, tòa nhà ICON4, 243A Đê La Thành, Láng, Hà Nội, Việt Nam','2026-09-30 10:02:38.852536','admin@gmail.com','<p>Cốc Cốc là công ty công nghệ Việt Nam, ra mắt trình duyệt Cốc Cốc năm 2013. Trình duyệt được xây dựng trên nền Chromium và tối ưu cho người dùng Việt Nam, đi kèm công cụ tìm kiếm tiếng Việt, tính năng tải video và nhiều tiện ích tích hợp.</p><p>Đội ngũ kỹ sư tại Hà Nội phát triển trình duyệt bằng C++, hệ thống tìm kiếm, nền tảng quảng cáo và các sản phẩm web, đồng thời nghiên cứu trải nghiệm người dùng trên máy tính và thiết bị di động.</p>','','Cốc Cốc',NULL,NULL,_binary ''),(25,'Hà Nội, Việt Nam','2026-09-30 10:02:38.878548','admin@gmail.com','<p>Viettel là Tập đoàn Công nghiệp – Viễn thông Quân đội, được thành lập năm 1989 và có trụ sở tại Hà Nội. Tập đoàn hoạt động trong viễn thông, công nghệ thông tin, công nghiệp quốc phòng, bưu chính và đầu tư quốc tế.</p><p>Các đơn vị công nghệ của Viettel gồm Viettel AI, Viettel Cyber Security, Viettel Solutions, Viettel IDC, Viettel Post và Viettel High Tech, tập trung vào AI, dữ liệu lớn, an ninh mạng, điện toán đám mây và hạ tầng 5G. Tập đoàn thường xuyên tuyển kỹ sư CNTT với chế độ thu nhập và đào tạo riêng cho khối công nghệ.</p>','','Viettel',NULL,NULL,_binary ''),(26,'Hà Nội, Việt Nam','2026-09-30 10:02:38.903598','admin@gmail.com','<p>FPT Software được thành lập năm 1999, là thành viên của Tập đoàn FPT và là một trong những công ty cung cấp dịch vụ phần mềm và chuyển đổi số lớn nhất Việt Nam. Công ty có hàng chục nghìn nhân sự tại nhiều quốc gia, phục vụ khách hàng toàn cầu trong ngân hàng – tài chính, sản xuất, ô tô, y tế và viễn thông.</p><p>FPT Software có văn phòng và trung tâm phát triển tại Hà Nội, TP. Hồ Chí Minh, Đà Nẵng, Gia Lai, Huế, Khánh Hòa và nhiều nơi khác, với các lĩnh vực trọng tâm như AI, dữ liệu, điện toán đám mây, ô tô thông minh và an ninh mạng.</p>','','FPT Software',NULL,NULL,_binary '');
